<?php
require_once __DIR__ . '/includes/visitor_portal.php'; $pdo=db();$visitor=current_visitor($pdo);
$s=$pdo->prepare('SELECT vb.*,b.title,b.author,b.cover_file FROM visitor_borrowing vb JOIN books b ON b.id=vb.book_id WHERE vb.visitor_id=? AND vb.return_date IS NULL ORDER BY vb.due_date');$s->execute([$visitor['id']]);$books=$s->fetchAll();visitor_portal_header('Borrowed Books',$visitor);
?><h2 class="mb-4">Borrowed Books</h2><?php if(!$books): ?><div class="alert alert-light border">You have no currently borrowed books.</div><?php else: ?><div class="row g-3"><?php foreach($books as $book): $remaining=(int)ceil((strtotime($book['due_date'])-strtotime('today'))/86400); ?><div class="col-md-6"><div class="card h-100 shadow-sm"><div class="card-body d-flex gap-3"><?php if($book['cover_file']): ?><img src="<?=e($book['cover_file'])?>" style="width:72px;height:102px;object-fit:cover" class="rounded" alt="Book cover"><?php else: ?><div class="bg-success text-white rounded d-flex align-items-center justify-content-center" style="width:72px;height:102px">📚</div><?php endif; ?><div><h5><?=e($book['title'])?></h5><div class="text-muted small mb-2"><?=e($book['author'])?></div><div class="small">Borrowed: <?=e($book['borrow_date'])?><br>Due: <?=e($book['due_date'])?><br><span class="<?= $remaining < 0 ? 'text-danger' : 'text-success' ?>"><?= $remaining < 0 ? abs($remaining).' day(s) overdue' : $remaining.' day(s) remaining' ?></span></div><span class="badge mt-2 <?= $remaining < 0 ? 'bg-danger' : 'bg-primary' ?>"><?= $remaining < 0 ? 'Overdue' : 'Borrowed' ?></span></div></div></div></div><?php endforeach; ?></div><?php endif; ?><?php visitor_portal_footer(); ?>
